#!/usr/bin/env python3
import json, glob, csv, re, os
from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill, Alignment
REG = {"11316": "Новосибирская область (11316)", "65": "Новосибирск (65)", "225": "Россия (225)"}
EXPORT = "2026-11-16"
MEAN = "число показов по запросам, содержащим фразу (широкое соответствие), за последние 30 дней — период по документации не подтверждён"
PERIOD = "последние ~30 дней до последней доступной даты (данные доступны до сентября 2026; см. журнал)"
HOMONYM = re.compile(r"остров пасман|мисс пасман|в москве")
def brand_cluster(q):
    rules = [("HR и вакансии", r"ваканс"), ("Цифровые сервисы", r"личный кабинет|анализ|результат"), ("Логистика и адреса", r"карамзин|блюхер|дзержинск|адрес|улиц|фото"),
             ("Контакт и запись", r"телефон|номер|регистратур|запис|запись"), ("Сопровождение и наблюдение", r"ведение беременности|мед комиссия"),
             ("Выбор: отзывы и цены", r"отзыв|цен"), ("Выбор: врачи и направления", r"гинеколог|узи|стоматолог|гастроэнтеролог|эндокринолог|гематолог|кардиолог|неврол|нефрол|спермограмм|фдт|врачи|проничева|паруликова"),
             ("Основатель", r"наталья михайловна|профессор пасман|биограф|сколько лет"), ("Навигация: сайт и официальный", r"сайт|официальн"),
             ("Навигация: бренд", r".")]
    for name, rx in rules:
        if re.search(rx, q): return name
STAGE = {"HR и вакансии": "вне пути пациента", "Цифровые сервисы": "после визита", "Логистика и адреса": "перед визитом", "Контакт и запись": "запись",
         "Сопровождение и наблюдение": "наблюдение", "Выбор: отзывы и цены": "выбор", "Выбор: врачи и направления": "выбор", "Основатель": "выбор (доверие)",
         "Навигация: сайт и официальный": "поиск клиники", "Навигация: бренд": "поиск клиники"}
def nb_stage(q):
    if re.search(r"подготовк", q): return "подготовка"
    if re.search(r"результат|расшифровк|хгч|тест", q): return "результаты"
    if re.search(r"после|восстановлен|реабилитац|швы|отек|отёк|диета|больничн|выделени|месячн|ощущени|рекомендац", q): return "после процедуры"
    if re.search(r"повторн|ведение|наблюден|контрол", q): return "контроль и наблюдение"
    if re.search(r"цен|стоим|отзыв|лучш|запис|клиник|новосибирск|сколько стоит|прием|консультац", q): return "выбор"
    return "прочее"
NBG = {}
for g, qs in {"Гинекология": ["гинеколог новосибирск","гинеколог эндокринолог новосибирск","ведение беременности новосибирск","подготовка к гистероскопии","после гистероскопии","после лапароскопии","узи малого таза подготовка"],
 "ЭКО и репродукция": ["эко новосибирск","эко по омс новосибирск","подготовка к эко","после переноса эмбрионов","хгч после эко","репродуктолог новосибирск"],
 "Урология": ["уролог новосибирск","после цистоскопии"], "Стоматология": ["стоматология новосибирск","имплантация зубов новосибирск","после удаления зуба","после имплантации зубов"],
 "Пластическая хирургия": ["пластический хирург новосибирск","после блефаропластики","после маммопластики"],
 "Общие этапы": ["результаты анализов","расшифровка анализов","повторный прием врача","после операции рекомендации"]}.items():
    for q in qs: NBG[q] = g
NOISE_NB = re.compile(r"шуб|квартал|велгия|деятельност|цели результат|кедров")
rows_brand, rows_nb, rows_excl = [], [], []
seen = set(); cap_notes = []
for p in sorted(glob.glob("raw/topRequests-*.json")):
    d = json.load(open(p)); src = d["request"]["phrase"]; reg = d["request"].get("regions", ["-"])[0]; n = d["request"].get("numPhrases")
    resp = d["response"]; isbrand = "пасман" in src or "pasman" in src
    if n and n >= 1000 and len(resp.get("results", [])) >= n: cap_notes.append(f"{src} ({REG.get(reg,reg)}): выдача обрезана лимитом numPhrases={n}")
    for typ in ("results", "associations"):
        for x in resp.get(typ, []):
            q = x["phrase"]; c = int(x["count"]); key = (q, reg, typ)
            if key in seen: continue
            seen.add(key)
            base = dict(запрос=q, частота=c, смысл=MEAN, период=PERIOD, регион=REG.get(reg, reg), устройства="все (параметр не задавался)", исходная=src, метод="topRequests (GetTop)",
                        тип="содержит фразу" if typ == "results" else "связанный запрос", дата=EXPORT)
            if typ == "associations":
                if isbrand:
                    rows_excl.append(dict(base, кластер="связанный запрос", этап="—", бренд="нет", комментарий="связанный, не содержит бренд; в анализ бренда не включён")); continue
                rows_excl.append(dict(base, кластер="связанный запрос", этап="—", бренд="нет", комментарий="связанный запрос категории; хранится отдельно")); continue
            if isbrand:
                if HOMONYM.search(q):
                    rows_excl.append(dict(base, кластер="однофамилец / другое значение", этап="—", бренд="неоднозначно", комментарий="не относится к клинике в Новосибирске")); continue
                cl = brand_cluster(q)
                rows_brand.append(dict(base, кластер=cl, этап=STAGE[cl], бренд="брендовый", комментарий="")); continue
            if NOISE_NB.search(q):
                rows_excl.append(dict(base, кластер="нерелевантное значение", этап="—", бренд="нет", комментарий="другое значение слова (эко-товары, ЖК и т.п.)")); continue
            rows_nb.append(dict(base, кластер=NBG.get(src, "прочее"), этап=nb_stage(q), бренд="небрендовый", комментарий="общий спрос категории, не свидетельство о пациентах клиники"))
# брендовые фразы с малой частотой без детализации (results пуст): сохраняем totalCount как строку исходной фразы
for p in sorted(glob.glob("raw/topRequests-*.json")):
    d = json.load(open(p)); src = d["request"]["phrase"]; reg = d["request"].get("regions", ["-"])[0]; r = d["response"]
    if ("пасман" in src) and not r.get("results") and (src, reg, "results") not in seen:
        seen.add((src, reg, "results")); cl = brand_cluster(src)
        rows_brand.append(dict(запрос=src, частота=int(r.get("totalCount", 0)), смысл=MEAN.replace("число показов", "totalCount: число показов"), период=PERIOD, регион=REG.get(reg, reg), устройства="все", исходная=src,
                               метод="topRequests (GetTop)", тип="totalCount исходной фразы (детализация пуста)", кластер=cl, этап=STAGE[cl], бренд="брендовый", комментарий="фраза ниже порога детализации — строк вложенных запросов API не вернул", дата=EXPORT))
POST = re.compile(r"после|результат|расшифровк|личный кабинет|анализ|ведение беременности|хгч|повторн|восстановлен|реабилитац|рекомендац|швы|отек|выделени|контрол")
rows_post = [r for r in rows_brand + rows_nb if POST.search(r["запрос"])]
# динамика
rows_dyn = []
for p in sorted(glob.glob("raw/dynamics-*.json")):
    d = json.load(open(p)); q = d["request"]["phrase"]; reg = d["request"]["regions"][0]
    for x in d["response"].get("results", []):
        rows_dyn.append(dict(запрос=q, регион=REG.get(reg, reg), месяц=x["date"][:7], частота=int(x["count"]), доля=round(float(x.get("share", 0)) * 100, 5), полнота="полный месяц", дата=EXPORT))
log = [json.loads(l) for l in open("api-log.jsonl")]
COLS = ["запрос", "частота", "смысл", "период", "регион", "устройства", "исходная", "метод", "тип", "кластер", "этап", "бренд", "комментарий", "дата"]
HEAD = ["запрос", "частота", "смысл показателя", "период", "регион и его ID", "устройства", "исходная фраза", "метод API", "тип результата", "кластер", "этап пути", "брендовый/небрендовый", "комментарий", "дата выгрузки"]
wb = Workbook(); hf = Font(bold=True, color="FFFFFF"); fill = PatternFill("solid", fgColor="09318D")
def sheet(title, header, rows, keys, first=False):
    ws = wb.active if first else wb.create_sheet()
    ws.title = title; ws.append(header)
    for c in ws[1]: c.font = hf; c.fill = fill; c.alignment = Alignment(wrap_text=True, vertical="top")
    for r in rows: ws.append([r.get(k, "") for k in keys])
    ws.freeze_panes = "A2"
    for i, w in enumerate([46, 10, 30, 24, 22, 14, 28, 18, 22, 26, 18, 14, 40, 12][:len(header)]): ws.column_dimensions[chr(65 + i)].width = w
key = lambda r: (r["регион"], -r["частота"])
sheet("Брендовые запросы", HEAD, sorted(rows_brand, key=key), COLS, first=True)
sheet("Сопровождение после визита", HEAD, sorted(rows_post, key=key), COLS)
sheet("Спрос категории без бренда", HEAD, sorted(rows_nb, key=lambda r: (r["кластер"], r["этап"], -r["частота"])), COLS)
sheet("Помесячная динамика", ["запрос", "регион и его ID", "месяц", "частота", "доля от всех запросов региона, %", "полнота месяца", "дата выгрузки"], rows_dyn, ["запрос", "регион", "месяц", "частота", "доля", "полнота", "дата"])
sheet("Исключённые и неоднозначные", HEAD, sorted(rows_excl, key=lambda r: (r["кластер"], -r["частота"])), COLS)
ws = wb.create_sheet("Журнал API и методология")
meth = [
 ["Методология и ограничения", ""],
 ["Подключение", "Yandex Cloud Search API v2, Wordstat: POST https://searchapi.api.cloud.yandex.net/v2/wordstat/topRequests и /dynamics. Ключ сервисного аккаунта подставляет прокси среды, в файлах его нет."],
 ["Документация", "Официальные страницы aistudio.yandex.ru из среды недоступны (DNS). Параметры проверены пробными вызовами; тариф — по выдержке официальной страницы тарифов в поисковой выдаче."],
 ["Тариф", "GetTop и GetDynamics: 20 ₽ за 1000 запросов с НДС; ошибки авторизации и внутренние ошибки сервера не тарифицируются (выдержка официальной страницы тарифов)."],
 ["Бюджет", f"Лимит прохода: 100 тарифицируемых вызовов (меньше 300 ₽). Выполнено успешных вызовов: {sum(1 for x in log if x['billable'])}; оценка стоимости ≈ {sum(1 for x in log if x['billable'])*0.02:.2f} ₽. Ошибок: {sum(1 for x in log if not x['billable'])}."],
 ["Последняя доступная дата", "Запрос динамики по 30.11.2026 вернул месяцы только по 2026-09. Октябрь 2026 и позже отсутствуют — согласуется с ограничением «статистика после 7 октября 2026 недоступна». Последний полный месяц: сентябрь 2026."],
 ["Период частоты topRequests", "В ответе период не указан; по сторонним описаниям — последние 30 дней. Не подтверждено документацией."],
 ["Регионы", "11316 — Новосибирская область, 65 — Новосибирск, 225 — Россия. ID проверены: ответы различаются по регионам. Город и область не складываются: город входит в область."],
 ["Устройства", "Параметр не задавался — все устройства."],
 ["Объём выдачи", "numPhrases до 2000 за вызов; пагинации нет. Брендовые наборы меньше лимита. Обрезаны лимитом: " + ("; ".join(sorted(set(cap_notes))) or "нет")],
 ["Типы результатов", "«содержит фразу» (results) и «связанный запрос» (associations) — разные типы; связанные запросы бренда в анализ не включены."],
 ["Вложенность", "Частоты вложенных фраз нельзя суммировать: «клиника пасман» входит в «пасман». Частота — показы запросов, не люди, не пациенты, не обращения."],
 ["Ошибки", "Вызов «пасман» с numPhrases=2000 и «ведение беременности новосибирск» стабильно возвращали 502; для «пасман» использован numPhrases=1000. 502 — ошибка сервиса, не ноль спроса."],
 ["Сайт клиники", "pasman-clinic.ru из среды недоступен. Направления и адреса — по выдержкам официального сайта в поисковой выдаче: гинекология, ЭКО и репродукция (в т.ч. по ОМС), урология, хирургия, онкология, пластическая хирургия, стоматология; адреса Карамзина 92, проспект Дзержинского 1/1, Блюхера 71/1. Фамилии врачей не собраны."],
 ["", ""], ["Журнал вызовов", ""], ["время (UTC)", "метод | параметры | статус | ошибка | тарифицируется | файл ответа"]]
for r in meth: ws.append(r)
for x in log: ws.append([x["at"], f"{x['method']} | {json.dumps(x['body'], ensure_ascii=False)} | {x['status']} | {x['error'] or ''} | {'да' if x['billable'] else 'нет'} | {x.get('cache','')}"])
ws.column_dimensions["A"].width = 28; ws.column_dimensions["B"].width = 160
for c in ws["A"]: c.font = Font(bold=True)
wb.save("pasman-wordstat-2026-11-16.xlsx")
allrows = rows_brand + rows_nb
with open("pasman-wordstat-clean.csv", "w", newline="", encoding="utf-8-sig") as f:
    w = csv.writer(f); w.writerow(HEAD); [w.writerow([r[k] for k in COLS]) for r in sorted(allrows, key=lambda r: (r["бренд"], r["регион"], -r["частота"]))]
uniq = len({r["запрос"] for r in allrows})
print(f"бренд {len(rows_brand)} | после визита {len(rows_post)} | категория {len(rows_nb)} | динамика {len(rows_dyn)} | исключено {len(rows_excl)} | уникальных запросов (бренд+категория) {uniq}")
print("cap:", cap_notes)
